def med(xs):
    s = sorted(xs)
    n, m = len(s), len(s) // 2
    return s[m] if n % 2 else (s[m - 1] + s[m]) / 2

def var(xs):
    mu = sum(xs) / len(xs)
    return sum((x - mu) ** 2 for x in xs) / len(xs)

def peak(xs):
    return max(xs)

def span(xs):
    return max(xs) - min(xs)

