def rms(xs):
    """Root mean square."""
    return (sum(x * x for x in xs) / len(xs)) ** 0.5


def med(xs):
    """Median."""
    s = sorted(xs)
    n = len(s)
    mid = n // 2
    return s[mid] if n % 2 else (s[mid - 1] + s[mid]) / 2


def var(xs):
    """Population variance."""
    n = len(xs)
    m = sum(xs) / n
    return sum((x - m) ** 2 for x in xs) / n


def peak(xs):
    """Maximum."""
    return max(xs)


def span(xs):
    """Max minus min."""
    return max(xs) - min(xs)
